use crate::Refusal;

/// Generated by capgen: the calls a plugin can make, one method per capability.
/// Only the kernel's bus gateway implements it; each plugin gets a host bound to
/// its own id, so a plugin never names itself or reaches a provider.
pub trait Host {
    /// Calls clock.now (clock.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn clock_now(&self) -> Result<u64, Refusal>;

    /// Calls echo.ping (echo.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn echo_ping(&self, n: u32) -> Result<u32, Refusal>;

    /// Calls tick.count (tick.cap). Inputs: the call's inputs. Output: its result or the refusal.
    fn tick_count(&self) -> Result<u32, Refusal>;
}
